/**
 * Agent-key verification for resource servers (docs/MCP-CLIENTS.md §4b).
 *
 * Better Auth's apiKey plugin exposes no cross-service verification route, so
 * this helper introspects the key at `<access-origin>/api/v2-introspect`
 * (RFC 7662), authenticating as this app's own OAuth client (RFC 6749 §2.3.1
 * client_secret_basic — the same credentials the token endpoint uses). Nothing
 * new is shared or stored.
 *
 * A key is an opaque, hashed record, so it cannot be verified offline. Caching
 * follows RFC 7662 §2.2: an answer is honoured for a short window, never past
 * the token's own `exp`, and a transport failure is never cached.
 */
const cache = new Map();
const DEFAULT_TTL_MS = 60_000;
const REQUEST_TIMEOUT_MS = 5_000;
/** The origin that serves the RFC 7662 introspection endpoint (issuer carries /api/auth). */
export function verifyEndpoint(issuer) {
    const origin = issuer.replace(/\/+$/, "").replace(/\/api\/auth$/, "");
    return `${origin}/api/v2-introspect`;
}
/**
 * `application/x-www-form-urlencoded` encoding (RFC 6749 §2.3.1 / Appendix B),
 * applied to each half of the Basic credential before base64. Space becomes `+`;
 * `encodeURIComponent` leaves `!'()*` alone, so those are escaped explicitly.
 */
function formEncode(value) {
    return encodeURIComponent(value)
        .replace(/%20/g, "+")
        .replace(/[!'()*]/g, (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`);
}
async function sha256Hex(value) {
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
    return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, "0")).join("");
}
/** Unix ms from an RFC 7662 `exp` (seconds), or null when absent/unparseable. */
function expToMs(exp) {
    return typeof exp === "number" && Number.isFinite(exp) ? exp * 1000 : null;
}
/**
 * Verify an agent key. Returns its info, or null when the key is unknown,
 * expired, revoked, or the verifier is unreachable (fail closed).
 */
export async function verifyAgentKey(cfg, key, opts = {}) {
    if (!key || !cfg.clientSecret)
        return null;
    const ttl = opts.ttlMs ?? DEFAULT_TTL_MS;
    const cacheKey = await sha256Hex(`${cfg.clientId}:${key}`);
    const hit = cache.get(cacheKey);
    if (hit && Date.now() < hit.until)
        return hit.info;
    let info = null;
    let authoritative = false;
    try {
        // RFC 7662 §2.1: form-encoded `token`, caller authenticated with Basic.
        // Bounded so a slow verifier fails closed instead of hanging the request.
        const abort = new AbortController();
        const timer = setTimeout(() => abort.abort(), REQUEST_TIMEOUT_MS);
        let res;
        try {
            res = await fetch(verifyEndpoint(cfg.issuer), {
                method: "POST",
                headers: {
                    "content-type": "application/x-www-form-urlencoded",
                    authorization: `Basic ${btoa(`${formEncode(cfg.clientId)}:${formEncode(cfg.clientSecret)}`)}`,
                },
                body: new URLSearchParams({ token: key }).toString(),
                signal: abort.signal,
            });
        }
        finally {
            clearTimeout(timer);
        }
        if (res.ok) {
            // RFC 7662 §2.2 response shape.
            const body = (await res.json());
            authoritative = true;
            if (body.active) {
                info = {
                    userId: body.sub ?? null,
                    scopes: typeof body.scope === "string" ? body.scope.split(" ").filter(Boolean) : [],
                    expiresAt: body.exp ?? null,
                };
            }
        }
    }
    catch {
        info = null; // unreachable verifier = no key for THIS request
    }
    // Only an answer the authorization server actually gave may be remembered;
    // a timeout or a 5xx must not lock a valid key out for the cache window.
    if (authoritative) {
        const expMs = expToMs(info?.expiresAt);
        const until = Math.min(Date.now() + ttl, expMs ?? Number.POSITIVE_INFINITY);
        if (cache.size > 512)
            cache.clear();
        if (until > Date.now())
            cache.set(cacheKey, { at: Date.now(), until, info });
    }
    return info;
}
/** True when the key carries `scope`. */
export function keyHasScope(info, scope) {
    return info.scopes.includes(scope);
}
/** Heuristic: an agent key is opaque; access tokens are JWTs (three segments). */
export function looksLikeAgentKey(token) {
    return token.length > 0 && token.split(".").length !== 3;
}
