/**
 * Local JWT verification against hilir Access (AUTH-REBUILD.md §4.0).
 *
 * Uses `jose` — createRemoteJWKSet + jwtVerify — rather than hand-rolled
 * crypto. That is the whole point of the rewrite: let a standard library
 * verify EdDSA, never re-implement it.
 *
 * No Service Binding, no D1, no introspection call. Issuer is
 * `https://access.hilir.app/api/auth` (staging:
 * `https://access-v2.hilir.app/api/auth`), JWKS at `${issuer}/jwks`.
 */
import { createRemoteJWKSet, jwtVerify } from "jose";
/** One remote JWKS per URL; jose caches keys and refetches on an unknown kid. */
const jwksByUrl = new Map();
function jwksFor(url) {
    let set = jwksByUrl.get(url);
    if (!set) {
        set = createRemoteJWKSet(new URL(url), {
            cacheMaxAge: 5 * 60_000,
            cooldownDuration: 30_000,
        });
        jwksByUrl.set(url, set);
    }
    return set;
}
/**
 * Verify an access token. Returns the user, or null for any failure
 * (bad signature, expired, wrong issuer/audience, malformed). Never throws.
 */
export async function verify(token, opts) {
    try {
        const jwksUrl = opts.jwksUrl ?? `${opts.issuer.replace(/\/+$/, "")}/jwks`;
        const { payload } = await jwtVerify(token, jwksFor(jwksUrl), {
            issuer: opts.issuer,
            audience: opts.audience,
            // EdDSA/Ed25519 only — the estate decision (PLAN.md §1). Never ES256.
            algorithms: ["EdDSA"],
            clockTolerance: opts.clockToleranceSec ?? 5,
        });
        const claimed = typeof payload.scope === "string" ? payload.scope : "";
        const scope = claimed.split(" ").filter((part) => part.length > 0);
        return {
            sub: String(payload.sub ?? ""),
            ...(typeof payload.email === "string" ? { email: payload.email } : {}),
            ...(typeof payload.name === "string" ? { name: payload.name } : {}),
            scope,
            claims: payload,
        };
    }
    catch {
        return null;
    }
}
/** Extract a bearer token from an Authorization header, or null. */
export function bearerToken(request) {
    const raw = (request.headers.get("authorization") ?? "").trim();
    if (raw.toLowerCase().startsWith("bearer ") !== true)
        return null;
    const token = raw.slice(7).trim();
    return token.length > 0 ? token : null;
}
/**
 * Scope gate. 401 when unauthenticated, 403 when authenticated but unscoped —
 * the estate rule (verification list item 6: a write without its scope must be
 * 403, not 401).
 */
export function requireScope(user, scope) {
    if (!user)
        return { ok: false, status: 401, body: { error: "unauthorized" } };
    if (scope && !user.scope.includes(scope)) {
        return { ok: false, status: 403, body: { error: "forbidden", required: scope } };
    }
    return { ok: true, user };
}
