/**
 * MCP resource-server discovery (MCP 2025-06-18 Authorization + RFC 9728).
 *
 * The spec makes two things mandatory for an HTTP MCP server that requires
 * authorization:
 *   1. serve Protected Resource Metadata at
 *      `/.well-known/oauth-protected-resource`, naming the authorization
 *      server(s) — RFC 9728 §3;
 *   2. send `WWW-Authenticate: Bearer resource_metadata="<that URL>"` on a 401
 *      — RFC 9728 §5.1.
 * Agents (Claude Code, ZCode, Copilot Studio "Dynamic discovery") use these to
 * find hilir Access without being told. One implementation here so every app
 * advertises the same shape.
 */
export const PROTECTED_RESOURCE_METADATA_PATH = "/.well-known/oauth-protected-resource";
/**
 * The metadata document for one app.
 * `resource` must be exactly the token audience this server validates.
 */
export function protectedResourceMetadata(cfg, opts = {}) {
    const resource = (opts.resource ?? cfg.resource ?? "").replace(/\/+$/, "");
    return {
        resource,
        authorization_servers: [cfg.issuer.replace(/\/+$/, "")],
        ...(opts.scopes && opts.scopes.length > 0 ? { scopes_supported: opts.scopes } : {}),
        bearer_methods_supported: ["header"],
        ...(opts.documentation ? { resource_documentation: opts.documentation } : {}),
    };
}
/**
 * The `WWW-Authenticate` value for a 401 from this server (RFC 9728 §5.1):
 * it tells the client where the metadata lives, so it can start OAuth.
 */
export function wwwAuthenticate(resource, extra = {}) {
    const metadataUrl = `${resource.replace(/\/+$/, "")}${PROTECTED_RESOURCE_METADATA_PATH}`;
    const parts = [`Bearer resource_metadata="${metadataUrl}"`];
    if (extra.error)
        parts.push(`error="${extra.error}"`);
    if (extra.scope)
        parts.push(`scope="${extra.scope}"`);
    return parts.join(", ");
}
