/**
 * OIDC client for hilir apps (AUTH-REBUILD.md §4.0).
 *
 * Authorization-code + PKCE against hilir Access. The app owns only its own
 * host cookies; the domain-wide `.hilir.app` session cookie belongs to Access
 * and makes sign-in silent — apps never read or validate it.
 *
 * Endpoints come from the issuer's discovery document, never hard-coded, so
 * staging → production is a config change (`issuer`) and nothing else.
 */
const DEFAULT_SCOPES = ["openid", "profile", "email", "offline_access"];
const DISCOVERY_TTL_MS = 10 * 60_000;
const discoveryCache = new Map();
export async function discover(cfg) {
    const base = cfg.issuer.replace(/\/+$/, "");
    const cached = discoveryCache.get(base);
    if (cached && Date.now() - cached.at < DISCOVERY_TTL_MS)
        return cached.doc;
    const res = await fetch(`${base}/.well-known/openid-configuration`);
    if (!res.ok)
        throw new Error(`discovery failed: ${res.status}`);
    const doc = (await res.json());
    discoveryCache.set(base, { at: Date.now(), doc });
    return doc;
}
// --- cookie plumbing ---------------------------------------------------------
export function serializeCookie(spec) {
    const { name, value } = spec;
    const options = spec.options ?? {};
    const parts = [`${name}=${value}`, `Path=${options.path ?? "/"}`];
    if (options.maxAge !== undefined)
        parts.push(`Max-Age=${options.maxAge}`);
    if (options.httpOnly !== false)
        parts.push("HttpOnly");
    if (options.secure !== false)
        parts.push("Secure");
    parts.push(`SameSite=${options.sameSite ?? "Lax"}`);
    return parts.join("; ");
}
/** Minimal cookie reader — one header, no dependencies. */
export function readCookies(request) {
    const out = new Map();
    const header = request.headers.get("cookie") ?? "";
    for (const part of header.split(";")) {
        const eq = part.indexOf("=");
        if (eq <= 0)
            continue;
        const name = part.slice(0, eq).trim();
        if (name.length > 0)
            out.set(name, part.slice(eq + 1).trim());
    }
    return out;
}
export function cookieNames(cfg) {
    const prefix = cfg.cookiePrefix ?? "hilir";
    return {
        access: `${prefix}.access`,
        refresh: `${prefix}.refresh`,
        idToken: `${prefix}.id_token`,
        state: `${prefix}.state`,
        next: `${prefix}.next`,
    };
}
// --- PKCE --------------------------------------------------------------------
function b64u(bytes) {
    let bin = "";
    for (const b of bytes)
        bin += String.fromCharCode(b);
    return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}
function randomToken(bytes = 32) {
    const buf = new Uint8Array(bytes);
    crypto.getRandomValues(buf);
    return b64u(buf);
}
export async function pkceChallenge(verifier) {
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier));
    return b64u(new Uint8Array(digest));
}
/** Build the authorization URL and the state/verifier cookies for it. */
export async function login(cfg, opts = {}) {
    const doc = await discover(cfg);
    const names = cookieNames(cfg);
    const state = randomToken();
    const verifier = randomToken();
    const challenge = await pkceChallenge(verifier);
    const url = new URL(doc.authorization_endpoint);
    url.searchParams.set("client_id", cfg.clientId);
    url.searchParams.set("redirect_uri", cfg.redirectUri);
    url.searchParams.set("response_type", "code");
    url.searchParams.set("scope", (cfg.scopes ?? DEFAULT_SCOPES).join(" "));
    url.searchParams.set("state", state);
    url.searchParams.set("code_challenge", challenge);
    url.searchParams.set("code_challenge_method", "S256");
    if (cfg.resource)
        url.searchParams.set("resource", cfg.resource);
    const short = { maxAge: 600, httpOnly: true, secure: true, sameSite: "Lax" };
    const cookies = [
        serializeCookie({ name: names.state, value: `${state}.${verifier}`, options: short }),
    ];
    if (opts.next !== undefined) {
        cookies.push(serializeCookie({ name: names.next, value: encodeURIComponent(opts.next), options: short }));
    }
    return { url: url.toString(), cookies };
}
/** Exchange the authorization code, validating state against its cookie. */
export async function callback(cfg, url, request) {
    const doc = await discover(cfg);
    const names = cookieNames(cfg);
    const jar = readCookies(request);
    const clears = [names.state, names.next].map((name) => serializeCookie({ name, value: "", options: { maxAge: 0 } }));
    const error = url.searchParams.get("error");
    if (error) {
        return { ok: false, status: 400, error, cookies: clears };
    }
    const code = url.searchParams.get("code") ?? "";
    const state = url.searchParams.get("state") ?? "";
    const stored = jar.get(names.state) ?? "";
    const dot = stored.indexOf(".");
    const storedState = dot > 0 ? stored.slice(0, dot) : "";
    const verifier = dot > 0 ? stored.slice(dot + 1) : "";
    if (code.length === 0 || storedState.length === 0 || state !== storedState || verifier.length === 0) {
        return { ok: false, status: 400, error: "invalid_state", cookies: clears };
    }
    const body = new URLSearchParams({
        grant_type: "authorization_code",
        code,
        redirect_uri: cfg.redirectUri,
        code_verifier: verifier,
        client_id: cfg.clientId,
        ...(cfg.resource ? { resource: cfg.resource } : {}),
    });
    const headers = {
        "content-type": "application/x-www-form-urlencoded",
        accept: "application/json",
    };
    if (cfg.clientSecret) {
        const basic = btoa(`${encodeURIComponent(cfg.clientId)}:${encodeURIComponent(cfg.clientSecret)}`);
        headers.authorization = `Basic ${basic}`;
    }
    const res = await fetch(doc.token_endpoint, { method: "POST", headers, body: body.toString() });
    if (!res.ok) {
        return { ok: false, status: 400, error: `token_exchange_failed_${res.status}`, cookies: clears };
    }
    const tokens = (await res.json());
    const nextRaw = jar.get(names.next);
    const next = nextRaw !== undefined ? decodeURIComponent(nextRaw) : undefined;
    return { ok: true, tokens, next, cookies: [...clears, ...tokenCookies(cfg, tokens)] };
}
/** Cookies that carry the tokens to the app's own host. Refresh is host-only. */
export function tokenCookies(cfg, tokens) {
    const names = cookieNames(cfg);
    const accessMaxAge = tokens.expires_in ?? 900;
    const out = [
        serializeCookie({ name: names.access, value: tokens.access_token, options: { maxAge: accessMaxAge } }),
    ];
    if (tokens.refresh_token) {
        out.push(serializeCookie({ name: names.refresh, value: tokens.refresh_token, options: { maxAge: 30 * 86_400 } }));
    }
    if (tokens.id_token) {
        // Persisted for RP-Initiated Logout: the id_token's `sid` identifies the
        // Access session, so /logout can present it as `id_token_hint` and the
        // provider ends the session directly (no confirmation page). Same lifetime
        // as the refresh token — it stays valid for the whole SSO session.
        out.push(serializeCookie({ name: names.idToken, value: tokens.id_token, options: { maxAge: 30 * 86_400 } }));
    }
    return out;
}
/** Silent refresh. Returns null when the refresh token is no longer valid. */
export async function refresh(cfg, refreshToken) {
    const doc = await discover(cfg);
    const body = new URLSearchParams({
        grant_type: "refresh_token",
        refresh_token: refreshToken,
        client_id: cfg.clientId,
        ...(cfg.resource ? { resource: cfg.resource } : {}),
    });
    const headers = {
        "content-type": "application/x-www-form-urlencoded",
        accept: "application/json",
    };
    if (cfg.clientSecret) {
        const basic = btoa(`${encodeURIComponent(cfg.clientId)}:${encodeURIComponent(cfg.clientSecret)}`);
        headers.authorization = `Basic ${basic}`;
    }
    const res = await fetch(doc.token_endpoint, { method: "POST", headers, body: body.toString() });
    if (!res.ok)
        return null;
    return (await res.json());
}
/** Only same-origin, absolute paths survive as a post-login destination. */
export function safeNext(next) {
    if (next === undefined)
        return "/";
    if (next.startsWith("/") && next.startsWith("//") !== true)
        return next;
    return "/";
}
/**
 * The provider's end-session URL. Sign-out is a **browser navigation**: the
 * session cookie belongs to the IdP (HttpOnly, different host), so no app can
 * clear it — redirecting the browser is the only standard way to end it.
 */
export async function endSessionUrl(cfg, opts = {}) {
    const doc = await discover(cfg);
    if (!doc.end_session_endpoint)
        return null;
    const url = new URL(doc.end_session_endpoint);
    url.searchParams.set("client_id", cfg.clientId);
    if (opts.postLogoutRedirectUri) {
        url.searchParams.set("post_logout_redirect_uri", opts.postLogoutRedirectUri);
    }
    if (opts.idTokenHint) {
        url.searchParams.set("id_token_hint", opts.idTokenHint);
    }
    return url.toString();
}
/** Cookies an app clears on its own host when signing out. */
export function logoutCookies(cfg) {
    const names = cookieNames(cfg);
    return [
        names.access,
        names.refresh,
        names.idToken,
        names.state,
        names.next,
        "hilir.email",
        "hilir.sub",
    ].map((name) => serializeCookie({ name, value: "", options: { maxAge: 0 } }));
}
