/**
 * Framework glue for hilir apps (AUTH-REBUILD.md §4.0).
 *
 * One `createHilirAuth(config)` gives an app:
 *   authenticate(request) → { user, setCookies } | { user: null }
 *   handleLogin(request)     → 302 to Access (sets state/verifier cookies)
 *   handleCallback(request)  → exchanges the code, sets token cookies, 302 to next
 *   middleware(...)          → Hono and Express adapters over the above
 *
 * Order (AUTH-REBUILD §4.0): read the app's own cookies → verify with jose →
 * if expired and a refresh token exists, refresh and rotate → otherwise send
 * the browser to Access. The app never validates Access's session cookie.
 */
import { callback as exchangeCode, cookieNames, login as startLogin, readCookies, refresh as refreshTokens, safeNext, serializeCookie, } from "./oidc.js";
import { verify } from "./verify.js";
const MAX_ACCESS_COOKIE_AGE = 30 * 86_400;
function clearSpecs(cfg, names) {
    return names.map((name) => serializeCookie({ name, value: "", options: { maxAge: 0 } }));
}
export function createHilirAuth(config) {
    const names = cookieNames(config);
    const loginPath = config.loginPath ?? "/auth/login";
    const callbackPath = config.callbackPath ?? "/auth/callback";
    async function verifyToken(token) {
        if (token === undefined || token.length === 0)
            return null;
        return verify(token, {
            issuer: config.issuer,
            audience: config.clientId,
            ...(config.jwksUrl !== undefined ? { jwksUrl: config.jwksUrl } : {}),
        });
    }
    /** Resolve the caller from the app's own cookies, refreshing when needed. */
    async function authenticate(request) {
        const jar = readCookies(request);
        const current = await verifyToken(jar.get(names.access));
        if (current !== null)
            return { user: current, setCookies: [], clearRefresh: false };
        const refreshToken = jar.get(names.refresh);
        if (refreshToken === undefined || refreshToken.length === 0) {
            return { user: null, setCookies: [], clearRefresh: false };
        }
        const tokens = await refreshTokens(config, refreshToken);
        if (tokens === null) {
            return { user: null, setCookies: clearSpecs(config, [names.access, names.refresh]), clearRefresh: true };
        }
        const refreshed = await verifyToken(tokens.access_token);
        if (refreshed === null) {
            return { user: null, setCookies: clearSpecs(config, [names.access, names.refresh]), clearRefresh: true };
        }
        const setCookies = [
            serializeCookie({
                name: names.access,
                value: tokens.access_token,
                options: { maxAge: tokens.expires_in ?? 900 },
            }),
        ];
        if (tokens.refresh_token !== undefined) {
            setCookies.push(serializeCookie({
                name: names.refresh,
                value: tokens.refresh_token,
                options: { maxAge: MAX_ACCESS_COOKIE_AGE },
            }));
        }
        return { user: refreshed, setCookies, clearRefresh: false };
    }
    /** GET /auth/login?next=/path → redirect to Access with PKCE cookies set. */
    async function handleLogin(request) {
        const url = new URL(request.url);
        const next = url.searchParams.get("next") ?? undefined;
        const start = await startLogin(config, next !== undefined ? { next } : {});
        const headers = new Headers({ location: start.url, "cache-control": "no-store" });
        for (const cookie of start.cookies)
            headers.append("set-cookie", cookie);
        return new Response(null, { status: 302, headers });
    }
    /** GET /auth/callback?code=…&state=… → exchange, set cookies, redirect. */
    async function handleCallback(request) {
        const url = new URL(request.url);
        const result = await exchangeCode(config, url, request);
        if (result.ok !== true) {
            const headers = new Headers({ location: `${loginPath}?error=${encodeURIComponent(result.error)}` });
            for (const cookie of result.cookies)
                headers.append("set-cookie", cookie);
            return new Response(null, { status: 302, headers });
        }
        const headers = new Headers({ location: safeNext(result.next), "cache-control": "no-store" });
        for (const cookie of result.cookies)
            headers.append("set-cookie", cookie);
        return new Response(null, { status: 302, headers });
    }
    function isApi(path) {
        return (config.apiPrefixes ?? []).some((prefix) => path.startsWith(prefix));
    }
    /**
     * Hono adapter: `app.use("*", auth.hono())`. Subsequent handlers read
     * `c.get("hilirUser")`.
     */
    function hono() {
        return async (c, next) => {
            const result = await authenticate(c.req.raw);
            if (result.user !== null) {
                c.set("hilirUser", result.user);
                if (result.setCookies.length > 0) {
                    for (const cookie of result.setCookies)
                        c.header("set-cookie", cookie, { append: true });
                }
                await next();
                return;
            }
            if (isApi(c.req.path)) {
                const headers = new Headers({ "content-type": "application/json" });
                for (const cookie of result.setCookies)
                    headers.append("set-cookie", cookie);
                return new Response(JSON.stringify({ error: "unauthorized" }), { status: 401, headers });
            }
            const target = `${c.req.path}${new URL(c.req.raw.url).search}`;
            return c.redirect(`${loginPath}?next=${encodeURIComponent(target)}`);
        };
    }
    /** Express adapter: `app.use(auth.express())`. Handlers read `req.hilirUser`. */
    function express() {
        return async (req, res, next) => {
            const request = toRequest(req);
            const result = await authenticate(request);
            if (result.setCookies.length > 0)
                res.setHeader("Set-Cookie", result.setCookies);
            if (result.user !== null) {
                req.hilirUser = result.user;
                next();
                return;
            }
            const path = req.originalUrl ?? req.url ?? "/";
            if (isApi(path)) {
                res.statusCode = 401;
                res.setHeader("Content-Type", "application/json");
                res.end(JSON.stringify({ error: "unauthorized" }));
                return;
            }
            res.statusCode = 302;
            res.setHeader("Location", `${loginPath}?next=${encodeURIComponent(path)}`);
            res.end();
        };
    }
    return {
        authenticate,
        handleLogin,
        handleCallback,
        hono,
        express,
        names,
        paths: { login: loginPath, callback: callbackPath },
    };
}
function toRequest(req) {
    const host = typeof req.headers.host === "string" ? req.headers.host : "localhost";
    const path = req.originalUrl ?? req.url ?? "/";
    const headerPairs = [];
    for (const [key, value] of Object.entries(req.headers)) {
        if (typeof value === "string")
            headerPairs.push([key, value]);
        else if (Array.isArray(value))
            headerPairs.push([key, value.join(", ")]);
    }
    return new Request(`https://${host}${path}`, {
        method: req.method ?? "GET",
        headers: new Headers(headerPairs),
    });
}
